generalized-second-price-auction.pseudocode:
def gsp(bids, quality, slots, reserve):
    # 순위 점수 = 입찰가 × 품질지수
    score = {a: bids[a] * quality[a] for a in bids}
    ranked = sorted(score, key=score.get, reverse=True)
    result = []
    for i, a in enumerate(ranked[:slots]):
        if i + 1 < len(ranked):
            nxt = ranked[i + 1]  # 바로 아래 순위
            price = score[nxt] / quality[a]
        else:
            price = reserve  # 아래 순위 없음 → 최저가
        result.append((a, i + 1, price))  # 광고주, 지면, CPC
    return result

generator.pseudocode:
def is_generator(g, p):  # p: 소수, 군 Z_p*
    n = p - 1  # 군의 위수
    for q in prime_factors(n):
        # g^(n/q) = 1 이면 g는 진부분군에 속함
        if pow(g, n // q, p) == 1:
            return False
    return True  # 위수가 n → 생성원(원시근)

# is_generator(3, 7) → True, is_generator(2, 7) → False

generator-polynomial.pseudocode:
def crc_remainder(data_bits, gen_bits):
    # data_bits, gen_bits: '0'/'1' 문자열, 생성다항식 최고·최저 차수 계수는 1
    n = len(gen_bits) - 1  # 생성다항식 차수 = FCS 비트 수
    bits = list(data_bits + '0' * n)  # M(x)·x^n
    for i in range(len(data_bits)):
        if bits[i] == '1':  # 선두 비트가 1일 때만 XOR (모듈로-2 나눗셈)
            for j in range(len(gen_bits)):
                bits[i + j] = '0' if bits[i + j] == gen_bits[j] else '1'
    return ''.join(bits[-n:])  # 나머지 n비트 = FCS

def crc_check(frame_bits, gen_bits):
    n = len(gen_bits) - 1
    data, fcs = frame_bits[:-n], frame_bits[-n:]
    return crc_remainder(data, gen_bits) == fcs  # 재계산 값과 비교

# 예: crc_remainder('1101011011', '10011') → '1110'  (G(x) = x⁴+x+1)
